import math
from watch import *

FAILED=('failed','cancelled','budget_stopped','reconciliation')
def has(label,filename):
    return (ROOT/'trials'/label/(filename+'.json')).exists()
def checkpoint(report):
    ck=report.get('checkpoint_id') or report.get('checkpoint')
    if isinstance(ck,dict):ck=ck.get('id') or ck.get('checkpoint_id')
    if not isinstance(ck,str) or not ck: raise ValueError('No checkpoint in completed Gym result: '+str(list(report)))
    return ck
def metric(report):
    keys=['dev_bpb']
    for obj in (report,report.get('metrics',{}),report.get('evaluation',{})):
        if isinstance(obj,dict):
            for k in keys:
                if k in obj and isinstance(obj[k],(int,float)) and math.isfinite(obj[k]):
                    return obj[k]
    raise ValueError('No finite development score in completed Gym result: '+str(list(report)))
def resume(label,base,step):
    if has(label,'job-'+str(step)):return read('trials/'+label+'/job-'+str(step))
    r=result(label,base,0)
    score=metric(r)
    ck=checkpoint(r)
    p=dict(candidate_id=candidate(label),profile_id=PROFILE,target_update=step,checkpoint_id=ck)
    q=save('trials/'+label+'/quote-'+str(step),api('quote_experiment',**p))
    if q['start_update']"'!=base or q['"'target_update']"'!=step or q['"'checkpoint_id']"'!=ck or not q['"'affordable']:
        raise ValueError('Unexpected continuation quote for '+label)
    return save('trials/'+label+'/job-'+str(step),api('run_experiment',quote_id=q['id'],idempotency_key='continue-'+label+'-'+str(step)))
def stage(labels,base,step):
    pending=set(labels)
    while pending:
        for label in labels:
            if label not in pending:continue
            if has(label,'job-'+str(step)):
                pending.remove(label);continue
            if not has(label,'job-'+str(base)):
                v=jobstate(label,FINAL)
                if v['state'] in FAILED or (v['state']=='succeeded' and not result(label,FINAL,0).get('admitted')):
                    print('No admitted model for',label,flush=True);pending.remove(label)
                continue
            j=jobstate(label,base)
            if j['state']=='succeeded':
                outcome=result(label,base,0)
                print('Measured',label,base,metric(outcome),flush=True)
                job=resume(label,base,step)
                print('Continued',label,step,job['id'],flush=True)
                pending.remove(label)
            elif j['state'] in FAILED:
                print('Needs review',label,base,j['state'],j.get('error_code'),flush=True)
                pending.remove(label)
        if pending:time.sleep(30)
if __name__=='__main__':
    base,step,*labels=sys.argv[1:]
    stage(labels,int(base),int(step))
